from itertools import combinations, product
import heapq


def ledger(data, priority, tax_base):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        if priority == "revision_first":
            key = (event.get("revision", 0), position)
        else:
            key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    half_up = data["rounding"] == "half_up"

    def rounded(numerator):
        return ((numerator + 5000) // 10000 if half_up
                else numerator // 10000)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        base = raw if tax_base == "original" else net
        tax = rounded(base * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def resolve(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    options = []
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        options.append([None] + versions)

    best_vector = None
    best_versions = None
    for values in product(*options):
        installed = dict(zip(names, values))
        pending = [(name, bounds[0], bounds[1])
                   for name, bounds in data["roots"].items()]
        reached = set()
        graph = {}
        valid = True
        while pending:
            name, low, high = pending.pop()
            version = installed[name]
            if version is None or not low <= version <= high:
                valid = False
                break
            if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                valid = False
                break
            if name in reached:
                continue
            reached.add(name)
            row = next(row for row in packages[name]
                       if row["version"] == version)
            graph[name] = []
            for dependency in row.get("deps", []):
                feature = dependency.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dependency["name"]
                graph[name].append(other)
                pending.append((other, dependency["min"], dependency["max"]))

        if not valid or any(installed[name] is not None
                            for name in names if name not in reached):
            continue

        colors = {}

        def acyclic(name):
            if colors.get(name) == 1:
                return False
            if colors.get(name) == 2:
                return True
            colors[name] = 1
            if any(not acyclic(other) for other in graph.get(name, [])):
                return False
            colors[name] = 2
            return True

        if not all(acyclic(name) for name in reached):
            continue
        vector = tuple(installed[name] if installed[name] is not None else -1
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_versions = {name: installed[name] for name in names
                             if name in reached}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def schedule(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for selected in combinations(jobs, k):
        ids = {job["id"] for job in selected}
        if ids & blocked or not mandatory <= ids:
            continue
        counts = Counter(job["group"] for job in selected)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        timeline = []
        for job in selected:
            timeline.append((job["start"], 1))
            timeline.append((job["end"], -1))
        active = 0
        feasible = True
        for _, change in sorted(timeline, key=lambda item: (item[0], item[1])):
            active += change
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue

        value = sum(job["value"] for job in selected)
        ordered_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value
                or (value == best_value and ordered_ids > best_ids)):
            best_value, best_ids = value, ordered_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def routes(data):
    required = data.get("required", [])
    bits = {node: 1 << index for index, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bits.get(source, 0)
    coupons = data["coupons"]
    start = data["start"]
    initial = (source, initial_mask, coupons)
    distances = {initial: start}
    queue = [(start, source, initial_mask, coupons)]

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], remaining)]
            if remaining:
                discounted = max(1, edge["duration"] - edge.get("discount", 0))
                durations.append((discounted, remaining - 1))
            for duration, left in durations:
                when = depart + duration
                if when > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, left)
                if when < distances.get(next_state, float("inf")):
                    distances[next_state] = when
                    heapq.heappush(queue, (when, next_node, next_mask, left))
    return {"arrival": None}


